const b = msg.payload || {};
const now = new Date().toISOString();

msg.payload = {
  channel: b.channel || 'openwebui',
  user_id: b.user_id || 'anonymous',
  conversation_id: b.conversation_id || `conv-${Date.now()}`,
  message_id: b.message_id || `msg-${Date.now()}`,
  text: (b.text || b.input?.source_text || b.message || '').trim(),
  attachments: Array.isArray(b.attachments) ? b.attachments : [],
  timestamp: b.timestamp || now,
  reply_policy: b.reply_policy || 'same_channel',
  meta: b.meta || {}
};

msg.req_id = `${msg.payload.conversation_id}:${msg.payload.message_id}`;
msg.jarvis = msg.jarvis || {};
msg.jarvis.started_at = now;
msg.jarvis.intent = null;
msg.jarvis.tool = null;
msg.jarvis.route = null;
msg.jarvis.debug = true;
msg.jarvis_trace = [];

msg.jarvis_trace.push({
  step: 'normalize',
  time: now,
  text: msg.payload.text,
  channel: msg.payload.channel,
  user_id: msg.payload.user_id
});

node.status({fill:'blue', shape:'dot', text:'reçu'});
return msg;

msg.payload = {
  stage: 'input',
  req_id: msg.req_id,
  text: msg.payload.text,
  conversation_id: msg.payload.conversation_id,
  message_id: msg.payload.message_id
};
node.status({fill:'grey', shape:'ring', text:'entrée visible'});
return msg;

const text = (msg.payload.text || '').toLowerCase();

let intent = 'unknown';
let tool = null;
let route = 'unknown';

const wantsListNpm =
  text.includes('liste les service de npm') ||
  text.includes('liste les services de npm') ||
  text.includes('liste les proxy de npm') ||
  text.includes('liste les proxys de npm') ||
  text.includes('liste les services de nginx proxy manager') ||
  text.includes('nginx proxy manager') ||
  text.includes('proxy manager');

const wantsAddProxy =
  text.includes('ajoute un proxy') ||
  text.includes('crée un proxy') ||
  text.includes('cree un proxy') ||
  text.includes('nouveau proxy');

const wantsListProxmoxCt =
  text.includes('lister les ct de proxmox') ||
  text.includes('liste des ct de proxmox') ||
  text.includes('liste les ct de proxmox') ||
  text.includes('list.containers') ||
  text.includes('list_ct');

const wantsHealth =
  text.includes('health') ||
  text.includes('ping jarvis') ||
  text.includes('test jarvis') ||
  text.includes('etat jarvis') ||
  text.includes('état jarvis');

if (wantsListNpm) {
  intent = 'npm_list_services';
  tool = 'npm_service';
  route = 'tool';
} else if (wantsAddProxy) {
  intent = 'npm_add_proxy';
  tool = 'npm_service';
  route = 'tool';
} else if (wantsListProxmoxCt) {
  intent = 'proxmox_list_ct';
  tool = 'proxmox_ct';
  route = 'tool';
} else if (wantsHealth) {
  intent = 'healthcheck';
  tool = null;
  route = 'health';
}

msg.intent = intent;
msg.tool = tool;
msg.jarvis.intent = intent;
msg.jarvis.tool = tool;
msg.jarvis.route = route;

msg.jarvis_trace.push({
  step: 'detect_intent',
  time: new Date().toISOString(),
  text,
  intent,
  tool,
  route
});

const color = intent === 'unknown' ? 'red' : (route === 'health' ? 'blue' : 'green');
node.status({fill: color, shape: 'dot', text: `intent: ${intent}`});
return msg;

msg.payload = {
  stage: 'intent',
  req_id: msg.req_id,
  text: msg.payload.text,
  intent: msg.intent,
  tool: msg.tool,
  route: msg.jarvis.route
};
node.status({fill:'grey', shape:'ring', text:'intention visible'});
return msg;

const metaBaseRaw = msg.payload?.meta?.toolbox_runner_url;
const metaBase = typeof metaBaseRaw === 'string' ? metaBaseRaw.trim() : '';
const envBaseRaw = env.get('TOOLBOX_RUNNER_URL');
const envBase = typeof envBaseRaw === 'string' ? envBaseRaw.trim() : '';
const forceMetaBase = msg.payload?.meta?.force_toolbox_runner_url === true;

const base = forceMetaBase
  ? (metaBase || envBase || 'http://localhost:8030')
  : (envBase || metaBase || 'http://localhost:8030');

const baseSource = forceMetaBase
  ? (metaBase ? 'payload.meta.toolbox_runner_url(forced)' : (envBase ? 'env.TOOLBOX_RUNNER_URL' : 'fallback.http://localhost:8030'))
  : (envBase ? 'env.TOOLBOX_RUNNER_URL' : (metaBase ? 'payload.meta.toolbox_runner_url' : 'fallback.http://localhost:8030'));

const npmInstanceName = env.get('NPM_INSTANCE_NAME') || 'default';
const proxmoxSshTargetRaw = msg.payload?.meta?.proxmox_ssh_target;
const proxmoxSshTarget = typeof proxmoxSshTargetRaw === 'string' ? proxmoxSshTargetRaw.trim() : '';

const input = {
  source_text: msg.payload.text
};

if (msg.intent === 'npm_list_services') {
  input.operation = 'list_services';
  input.instance_name = npmInstanceName;
}

if (msg.intent === 'npm_add_proxy') {
  input.operation = 'plan_service_action';
  input.instance_name = npmInstanceName;
  input.action = 'add';
  input.note = 'Prévoir un parsing plus riche des domaines, upstreams et certificats';
}

if (msg.intent === 'proxmox_list_ct') {
  input.intent = 'list.containers';
  if (proxmoxSshTarget) {
    input.ssh_target = proxmoxSshTarget;
  }
}

msg.url = `${base}/v1/run`;
msg.method = 'POST';
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {
  tool: msg.tool,
  input,
  context: {
    req_id: msg.req_id,
    conversation_id: msg.payload.conversation_id,
    user_id: msg.payload.user_id,
    source: msg.payload.meta?.source || 'unknown'
  }
};

msg.jarvis_debug = msg.jarvis_debug || {};
msg.jarvis_debug.tool_call = {
  url: msg.url,
  method: msg.method,
  tool: msg.tool,
  base,
  base_source: baseSource,
  request_body: msg.payload
};

msg.jarvis_trace.push({
  step: 'prepare_tool_call',
  time: new Date().toISOString(),
  url: msg.url,
  method: msg.method,
  tool: msg.tool,
  base_source: baseSource,
  request_body: msg.payload
});

node.status({fill:'yellow', shape:'dot', text:`appel ${msg.tool}`});
return msg;

msg.payload = {
  stage: 'tool_request',
  req_id: msg.req_id,
  url: msg.url,
  tool: msg.tool,
  body: msg.payload
};
node.status({fill:'grey', shape:'ring', text:'requête outil visible'});
return msg;

const toolResult = msg.payload || {};
const ok = !!toolResult.ok;

msg.jarvis_trace.push({
  step: 'tool_response',
  time: new Date().toISOString(),
  tool: msg.tool,
  ok,
  payload: toolResult
});

msg.payload = {
  ok,
  message: toolResult.message || (ok ? 'Outil exécuté' : 'Outil en échec'),
  intent: msg.intent,
  tool: msg.tool,
  result: toolResult,
  debug: {
    req_id: msg.req_id,
    route: msg.jarvis.route,
    toolbox_runner_url: msg.url || null
  },
  trace: msg.jarvis_trace
};

node.status({fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'outil ok' : 'outil fail'});
return msg;

msg.jarvis_trace.push({
  step: 'health_response',
  time: new Date().toISOString(),
  ok: true
});

msg.payload = {
  ok: true,
  message: 'Jarvis flow opérationnel',
  intent: 'healthcheck',
  debug: {
    req_id: msg.req_id,
    route: msg.jarvis.route
  },
  trace: msg.jarvis_trace
};

node.status({fill:'green', shape:'dot', text:'health ok'});
return msg;

msg.jarvis_trace.push({
  step: 'unknown',
  time: new Date().toISOString(),
  reason: 'intent_not_matched'
});

msg.payload = {
  ok: false,
  message: 'Intention inconnue. Exemples: liste les services de npm ; ajoute un proxy ; lister les ct de proxmox ; ping jarvis',
  intent: 'unknown',
  debug: {
    req_id: msg.req_id,
    route: msg.jarvis.route,
    received_text: msg.payload.text
  },
  trace: msg.jarvis_trace
};

node.status({fill:'red', shape:'ring', text:'unknown'});
return msg;

msg.statusCode = 200;
node.status({fill:'blue', shape:'ring', text:'réponse prête'});
return msg;

msg.payload = {
  stage: 'output',
  req_id: msg.payload.debug?.req_id || msg.req_id,
  ok: msg.payload.ok,
  intent: msg.payload.intent,
  tool: msg.payload.tool || null,
  message: msg.payload.message
};
node.status({fill:'grey', shape:'ring', text:'sortie visible'});
return msg;

const err = msg.error || {};
const source = err.source || {};
const trace = Array.isArray(msg.jarvis_trace) ? msg.jarvis_trace : [];
const toolCall = msg.jarvis_debug?.tool_call || null;

msg.statusCode = 500;
msg.payload = {
  ok: false,
  message: 'Erreur dans le flow Jarvis',
  error: {
    message: err.message || 'unknown error',
    source_id: source.id || null,
    source_name: source.name || null,
    source_type: source.type || null
  },
  debug: {
    req_id: msg.req_id || null,
    hint: (err.message || '').includes('ECONNREFUSED')
      ? 'Connexion refusée vers le service cible. Vérifiez TOOLBOX_RUNNER_URL/meta.toolbox_runner_url et le port 8030.'
      : ((err.message || '').includes('EAI_AGAIN')
        ? 'Résolution DNS impossible vers le host configuré. Essayez meta.toolbox_runner_url = http://localhost:8030 dans le payload de test.'
        : null),
    tool_call: toolCall,
    trace_length: trace.length,
    last_trace: trace.length ? trace[trace.length - 1] : null
  }
};

node.status({fill:'red', shape:'dot', text:'erreur'});
return msg;
